head.script:
scwin.screenId = "jldfil16202";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(poll#searchpoll vs poll#registerpollform) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16202.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_poolList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_poolList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_poolList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_poolList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["questStatCd"] === '2') { if (typeof scwin.registerPoll === 'function') { await scwin.registerPoll(r["questNo"], r["questProgStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.registerPoll (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.registerPoll'); } return; }
        if (typeof scwin.alert === 'function') { scwin.alert("설문이 종료되었습니다."); } else { console.error('[sdd] 행 동작 미정의: scwin.alert (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.alert'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_poolList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/poll.do",
        ref: "dma_SearchReq",
        target: "dlt_poolList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16202.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_RegisterPoll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_RegisterPoll = async function () {
    const sbmOptions = {
        id: "tx_fn_RegisterPoll",
        method: "post",
        action: "/support/poll.do",
        ref: "dma_RegisterPollReq",
        target: "dlt_poolList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16202.tx_fn_RegisterPoll" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_poolList_fmt_questTitle
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_poolList_fmt_questTitle = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_poolList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "questStatCd") ?? '') : '');
        if (v === '2') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "questTitle") : '') ?? '') + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "questTitle") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_poolList.questTitle" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_poolList_fmt_column5
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_poolList_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_poolList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "questProgStatCd") ?? '') : '');
        if (v === '2') { return "작성완료"; }
        if (v === '1') { return "작성중"; }
        return "미작성";
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_poolList.column5" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.pollListForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchPoll');
    frm.action = 'poll.do';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerPoll
 * @author Inswave
 * @date 2026. 09. 29
 * @param _questNo _questProgStatCd
 * @returns
 * @hidden N
*/
scwin.registerPoll = async function (_questNo, _questProgStatCd) {
    /* sdd-asis-lifecycle:begin fn_RegisterPoll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.pollListForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('questNo', _questNo);
    $c.util.getComponent('dma_SearchReq').set('questProgStatCd', _questProgStatCd);
    $c.util.getComponent('dma_SearchReq').set('method', 'registerPollForm');
    frm.action = 'poll.do';
    { const nr = await scwin.tx_fn_RegisterPoll(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16200/jldfil16200.xml", { "questNo": _questNo, "questProgStatCd": _questProgStatCd, "method": 'registerPollForm' }); } };
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_50_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_50_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_50.page' }); } scwin.search(); };
